suppressPackageStartupMessages({library(data.table);library(igraph);library(parallel)})
source(file.path(Sys.getenv("ANALYSIS_ROOT"),"00_config","00_config.R"));source(file.path(ANALYSIS_ROOT,"00_config","00_helpers.R"));base<-file.path(ANALYSIS_ROOT,"04_genus_host_network");make_dirs(base)
ew<-fread(file.path(base,"tables","02_network_edge_weights.tsv"),sep="\t");ed<-ew[,.(from=paste0("V:",virus_node),to=paste0("H:",host_family),weight=as.numeric(weight))];nodes<-data.table(name=unique(c(ed$from,ed$to)));nodes[,type:=startsWith(name,"H:")];g<-graph_from_data_frame(ed,FALSE,nodes);E(g)$weight<-ed$weight;pr<-bipartite_projection(g,multiplicity=TRUE);pg<-if(sum(startsWith(V(pr$proj1)$name,"V:"))>=sum(startsWith(V(pr$proj2)$name,"V:")))pr$proj1 else pr$proj2;pg<-simplify(as.undirected(pg),remove.multiple=TRUE,remove.loops=TRUE)
metric<-function(x){if(vcount(x)<3||ecount(x)<2)return(c(C=NA,L=NA));co<-components(x);gc<-induced_subgraph(x,V(x)[co$membership==which.max(co$csize)]);c(C=transitivity(gc,type="global"),L=mean_distance(gc,directed=FALSE,unconnected=FALSE))}
obs<-metric(pg);worker<-function(i){set.seed(SEED+700000L+i);gr<-rewire(pg,with=keeping_degseq(niter=max(100L,10L*ecount(pg))));metric(gr)};rr<-mclapply(seq_len(FIG5_PROJECTION_NULL_ITER),worker,mc.cores=min(NCORES,FIG5_PROJECTION_NULL_ITER));mat<-do.call(rbind,rr);dt<-data.table(iteration=seq_len(nrow(mat)),random_transitivity=mat[,"C"],random_path_length=mat[,"L"]);write_tsv(dt,file.path(base,"tables","17_projection_degree_preserving_randomization.tsv"));cr<-mean(dt$random_transitivity,na.rm=TRUE);lr<-mean(dt$random_path_length,na.rm=TRUE);sigma<-(obs["C"]/cr)/(obs["L"]/lr);sumr<-data.table(observed_transitivity=obs["C"],random_mean_transitivity=cr,observed_path_length=obs["L"],random_mean_path_length=lr,small_world_sigma=sigma,random_iterations=FIG5_PROJECTION_NULL_ITER);write_tsv(sumr,file.path(base,"tables","18_projection_small_world_summary.tsv"));cat("Fig5 projection randomization PASS\n");print(sumr)
